local HatMaker = {}
local PRODUCTS = {
    simple_felt_cap = { name = "Preprosta filcana kapa", woolCost = 2, leatherCost = 1, time = 3, cost = 40, beauty = 18, happiness = 1, warmth = 18, description = "Preprosta filcana kapa za vsakdan." },
    beaver_felt_hat = { name = "Bober filc klobuk", woolCost = 2, leatherCost = 2, time = 6, cost = 130, beauty = 35, happiness = 2, warmth = 30, prestige = 3, description = "Bober filc klobuk za trgovce." }
    , silver_banded_hat = { name = "Srebrnopasni klobuk", woolCost = 2, silverCost = 1, leatherCost = 2, time = 9, cost = 320, beauty = 50, happiness = 2, warmth = 38, prestige = 8, description = "Srebrnopasni klobuk za plemiče." },
    gold_trimmed_hat = { name = "Zlatookrasni klobuk", woolCost = 2, goldCost = 1, silverCost = 1, leatherCost = 2, time = 13, cost = 760, beauty = 65, happiness = 3, warmth = 45, prestige = 16, description = "Zlatookrasni klobuk za visoke plemiče." },
    jewel_pinned_hat = { name = "Draguljnopripeti klobuk", woolCost = 2, goldCost = 1, silverCost = 1, leatherCost = 2, jewelCost = 1, time = 17, cost = 1700, beauty = 80, happiness = 5, warmth = 52, prestige = 28, description = "Klobuk z draguljno priponko za visoko plemstvo." },
    royal_grand_hat = { name = "Kraljevski veliki klobuk", woolCost = 3, goldCost = 2, silverCost = 2, leatherCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, beauty = 95, happiness = 12, warmth = 65, prestige = 58, description = "Veliki kraljevski klobuk z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    hat_workshop = { name = "Klobučarska delavnica", cost = { gold = 220, wood = 100, stone = 100, wool = 6, leather = 6 }, upkeep = 5, qualityBonus = 5 },
    felt_loft = { name = "Filcna podstrešje", cost = { gold = 880, wood = 240, stone = 220, silver = 6, wool = 8 }, upkeep = 20, qualityBonus = 18 },
    master_hatter_atelier = { name = "Mojstrski klobučarski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_hatter_palace = { name = "Kraljevska klobučarska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
HatMaker.woolStock = 16; HatMaker.leatherStock = 12; HatMaker.silverStock = 6; HatMaker.goldStock = 6; HatMaker.jewelStock = 4; HatMaker.pearlStock = 4
HatMaker.productStock = {}; HatMaker.buildings = {}; HatMaker.maker = nil; HatMaker.activeMaking = {}; HatMaker.totalProducts = 0; HatMaker.dayTimer = 0
function HatMaker.init() HatMaker.woolStock=16; HatMaker.leatherStock=12; HatMaker.silverStock=6; HatMaker.goldStock=6; HatMaker.jewelStock=4; HatMaker.pearlStock=4; HatMaker.productStock={}; HatMaker.buildings={}; HatMaker.maker=nil; HatMaker.activeMaking={}; HatMaker.totalProducts=0; HatMaker.dayTimer=0; print("[HatMaker] Royal Hat Maker System initialized (6 products, 4 buildings)") end
function HatMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HatMaker.maker={name=n or ("Klobučar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klobučar najet: %s (spretnost: %d)",HatMaker.maker.name,s),"success") end; return true end
function HatMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HatMaker.build(id) local ok,e=HatMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HatMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HatMaker.getQualityBonus() local b=0; for _,bd in ipairs(HatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HatMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woolCost and HatMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.leatherCost and HatMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatMaker.buildings==0 then return false,"Potrebna klobučarska delavnica" end; if not HatMaker.maker then return false,"Potreben klobučar" end; return true end
function HatMaker.make(pt,qty) qty=qty or 1; local ok,e=HatMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woolCost then HatMaker.woolStock=HatMaker.woolStock-d.woolCost*qty end; if d.leatherCost then HatMaker.leatherStock=HatMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatMaker.silverStock=HatMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatMaker.goldStock=HatMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatMaker.jewelStock=HatMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatMaker.pearlStock=HatMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatMaker.maker then t=math.max(1,t-math.floor(HatMaker.maker.skill/13)) end; table.insert(HatMaker.activeMaking,{id="hat_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,warmth=d.warmth or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HatMaker.completeMaking(m) local q=1.0+(HatMaker.getQualityBonus()/100); if HatMaker.maker then q=q+(HatMaker.maker.skill/140) end; q=math.min(2.5,q); HatMaker.productStock[m.productType]=(HatMaker.productStock[m.productType] or 0)+m.quantity; HatMaker.totalProducts=HatMaker.totalProducts+m.quantity; if m.warmth>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+math.floor(m.warmth/30)) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HatMaker.maker then HatMaker.maker.itemsMade=HatMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HatMaker.maker.skill=math.min(100,HatMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klobuk izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hat.completed",{productName=m.productName,beauty=m.beauty,warmth=m.warmth,prestige=m.prestige,happiness=m.happiness}) end end
function HatMaker.update(dt) if not _G.state then return end; HatMaker.dayTimer=HatMaker.dayTimer+dt; if HatMaker.dayTimer>=30 then HatMaker.dayTimer=0; for i=#HatMaker.activeMaking,1,-1 do local m=HatMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatMaker.completeMaking(m); table.remove(HatMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HatMaker.getStats() return {woolStock=HatMaker.woolStock,leatherStock=HatMaker.leatherStock,silverStock=HatMaker.silverStock,goldStock=HatMaker.goldStock,jewelStock=HatMaker.jewelStock,pearlStock=HatMaker.pearlStock,productStock=HatMaker.productStock,numBuildings=#HatMaker.buildings,hasMaker=HatMaker.maker~=nil,makerName=HatMaker.maker and HatMaker.maker.name or "—",makerSkill=HatMaker.maker and HatMaker.maker.skill or 0,activeMaking=#HatMaker.activeMaking,totalProducts=HatMaker.totalProducts} end
return HatMaker
